export async function searchDocuments(
  input: SearchQueryInput,
): Promise<Page<SearchIndexRow>> {
  const db = getDb();
  const sort = { sortColumn: searchIndex.indexedAt, idColumn: searchIndex.id };

  const filters = compact(
    orgPredicate(searchIndex.orgId, input.orgId),
    like(searchIndex.content, `%${input.q}%`),
    input.kinds.length === 0
      ? undefined
      : inArray(searchIndex.subjectKind, [...input.kinds]),
    input.projectId === undefined
      ? undefined
      : eq(searchIndex.projectId, input.projectId),
    sql`case ${searchIndex.subjectKind}
      when 'project' then exists (select 1 from projects p where p.id = ${searchIndex.subjectId} and p.org_id = ${searchIndex.orgId} and p.archived_at is null)
      when 'issue' then exists (select 1 from issues i join projects p on p.id = i.project_id and p.org_id = i.org_id where i.id = ${searchIndex.subjectId} and i.org_id = ${searchIndex.orgId} and i.archived_at is null and p.archived_at is null)
      when 'comment' then exists (select 1 from comments c join issues i on i.id = c.issue_id and i.org_id = c.org_id join projects p on p.id = i.project_id and p.org_id = i.org_id where c.id = ${searchIndex.subjectId} and c.org_id = ${searchIndex.orgId} and c.archived_at is null and i.archived_at is null and p.archived_at is null)
      else 0 end = 1`,
  );

  const total = db
    .select({ value: count() })
    .from(searchIndex)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(searchIndex)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(searchIndex.indexedAt), desc(searchIndex.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => row,
    (row) => ({ id: row.id, sortValue: row.indexedAt }),
  );
}

